/**
 * Compute AABB bounds for each chunk of splats.
 * Used for hierarchical frustum culling at runtime.
 *
 * @param {Float32Array} positions - Positions array (count * 3)
 * @param {number} count - Number of splats
 * @param {number} [chunkSize=256] - Number of splats per chunk (should match workgroup size)
 * @param {Float32Array} [scales] - Optional scales array (count * 3, log-space) for AABB padding
 * @param {number} [maxStdDev=2.83] - Maximum std devs for Gaussian extent (default sqrt(8))
 * @returns {Float32Array} Chunk bounds array (numChunks * 6): [minX, minY, minZ, maxX, maxY, maxZ] per chunk
 */
export function computeChunkBounds(positions: Float32Array, count: number, chunkSize?: number, scales?: Float32Array, maxStdDev?: number): Float32Array;
/**
 * Apply Morton ordering to parsed Gaussian Splatting data.
 *
 * Reorders all splat arrays (positions, scales, rotations, colors, shCoefficients)
 * by Morton code to improve GPU cache locality during rendering.
 *
 * @param {Object} data - Parsed splat data from loader
 * @param {Float32Array} data.positions - Positions (count * 3)
 * @param {Float32Array} data.scales - Scales (count * 3)
 * @param {Float32Array} data.rotations - Rotations (count * 4)
 * @param {Float32Array} data.colors - Colors (count * 4)
 * @param {Float32Array} [data.shCoefficients] - SH coefficients (optional)
 * @param {number} data.count - Number of splats
 * @param {number} data.shDegree - SH degree
 * @returns {Object} Reordered data with same structure
 */
export function applyMortonOrdering(data: {
    positions: Float32Array;
    scales: Float32Array;
    rotations: Float32Array;
    colors: Float32Array;
    shCoefficients?: Float32Array;
    count: number;
    shDegree: number;
}): any;
